  function addParameter(){mutate(next=>next.parameters.push({id:id('parameter'),label:'Parameter',type:'number',default:0,min:0,max:100}));}
  function parameterType(index:number,type:string){mutate(next=>{const previous=next.parameters[index];next.parameters[index]={id:previous.id,label:previous.label,type,default:type==='number'?0:type==='boolean'?false:type==='color'?'#72d8ca':'Label',...(type==='number'?{min:0,max:100}:{})} as WidgetParameter;});}
  async function importAsset(file?:File){if(!file)return;try{if(file.size>2*1024*1024)throw Error('Assets must be at most 2 MiB.');if(!['image/png','image/jpeg','image/webp','audio/wav','audio/x-wav'].includes(file.type))throw Error('Use PNG, JPEG, WebP or PCM16 WAV.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));mutate(next=>{(next.assets??=[]).push({id:id('asset'),mime:(file.type==='audio/x-wav'?'audio/wav':file.type) as 'audio/wav',base64:btoa(binary)});});}catch(e){error=e instanceof Error?e.message:String(e);}}
  function simulation(event:string){const declaration=draft.behavior.events.find(item=>item.id===event);const updates:Record<string,Scalar>={},feedback:Record<string,BehaviorFeedback>={};for(const signal of draft.behavior.signals){if(!declaration?.updates?.includes(signal.id))continue;if(signal.source==='input')updates[signal.id]=inputValues[signal.id]??signal.initial;else if(signal.source==='feedback'){const status=(qualities[signal.id]??'unknown') as BehaviorFeedback['status'];feedback[signal.id]={status,...(status==='fresh'||status==='stale'?{value:feedbackValues[signal.id]??signal.initial,provenance:'game-confirmed',sourceKind:'simulator'}:{})};}}tryPlayer?.dispatch(event,updates,feedback);}
  onMount(()=>()=>fence.invalidate());
</script>

<svelte:window onkeydown={keyboard}/>
<section class="generic-designer" aria-label="Generic widget designer">
  <PageHeader title={draft.title} eyebrow="WIDGET DESIGNER" subtitle="Design visuals, configure behavior, compile finished pixels." onback={cancel} backDisabled={saving}>{#snippet titleContent()}<input class="title" aria-label="Widget name" disabled={saving} value={draft.title} onchange={e=>mutate(next=>next.title=e.currentTarget.value)}/>{/snippet}{#snippet actions()}<button title="Undo" aria-label="Undo" disabled={!history.past.length||saving} onclick={undo}><Icon name="undo" size={16}/></button><button title="Redo" aria-label="Redo" disabled={!history.future.length||saving} onclick={redo}><Icon name="redo" size={16}/></button><span class="save-action" title={saveDisabledReason||undefined}><button onclick={save} disabled={!!saveDisabledReason} title={saveDisabledReason||undefined}><Icon name="save" size={16}/>{saving?'Saving…':'Save'}</button></span>{/snippet}</PageHeader>
  <nav aria-label="Designer workspaces">{#each tabs as workspace}<button class:active={tab===workspace} aria-pressed={tab===workspace} onclick={()=>openWorkspace(workspace)}><Icon name={({Design:'pencil',States:'layout',Signals:'network',Motion:'play',Sound:'activity',Preview:'monitor'} as Record<string,string>)[workspace]} size={16}/>{workspace}</button>{/each}</nav>
  <div class="buildbar" inert={saving}><label>Target width<input aria-label="Compiled width" type="number" min="1" max="2048" value={targetWidth} onchange={e=>{targetWidth=e.currentTarget.valueAsNumber;invalidate();}}/></label><label>Height<input aria-label="Compiled height" type="number" min="1" max="2048" value={targetHeight} onchange={e=>{targetHeight=e.currentTarget.valueAsNumber;invalidate();}}/></label><label class="check"><input type="checkbox" bind:checked={motion} onchange={invalidate}/>Animation</label><label class="check"><input type="checkbox" bind:checked={audioEnabled} onchange={invalidate}/>Audio</label><button class="primary" onclick={()=>void compile()} disabled={busy||saving}><Icon name="zap" size={16}/>Compile</button>{#if busy}<button onclick={invalidate}><Icon name="stop" size={16}/>Cancel</button>{/if}<button onclick={download} disabled={!compiled||busy}><Icon name="download" size={16}/>Export</button><span role="status">{progress||(!compiled?'Compile required':'Compiled')}</span></div>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  <div class="workspace" inert={saving} class:design={tab==='Design'}>
  {#if tab==='States'||tab==='Signals'}
    <WidgetGraphEditor source={draft} mode={tab} onchange={graphChange} onappearance={openAppearance} onmode={mode=>tab=mode} live={tryState}/>
  {:else if tab==='Design'}
    <aside aria-label="Layers"><h3>Layers <small>back to front</small></h3><p class="layer-hint">Drop on a group to nest; between layers to reorder.</p><ol class="layers">{#each visibleLayers as entry (entry.node.id)}<li data-layer-id={entry.node.id} class:dragging={draggedLayer===entry.node.id} class:drop-before={layerDrop?.id===entry.node.id&&layerDrop.placement==='before'} class:drop-inside={layerDrop?.id===entry.node.id&&layerDrop.placement==='inside'} class:drop-after={dropAfterLayer===entry.node.id}>{#if entry.node.kind==='group'}<button class="group-toggle" class:expanded={!collapsedGroups.has(entry.node.id)} style:left={`${6+entry.depth*14}px`} aria-label={`${collapsedGroups.has(entry.node.id)?'Expand':'Collapse'} ${entry.node.label??entry.node.id}`} aria-expanded={!collapsedGroups.has(entry.node.id)} onclick={()=>toggleGroup(entry.node.id)}><Icon name="chevron" size={12}/></button>{/if}<button class="layer-select" class:active={selected===entry.node.id} style:padding-left={`${26+entry.depth*14}px`} aria-expanded={entry.node.kind==='group'?!collapsedGroups.has(entry.node.id):undefined} draggable={!saving} title="Drag onto a group to nest, or between layers to reorder. Alt+arrows also reorder, indent or outdent." aria-keyshortcuts="Alt+ArrowUp Alt+ArrowDown Alt+ArrowLeft Alt+ArrowRight" onclick={()=>selectLayer(entry.node)} onkeydown={e=>layerKey(e,entry.node.id)} ondragstart={e=>startLayerDrag(e,entry.node.id)} ondragover={e=>overLayer(e,entry.node.id)} ondrop={e=>dropLayer(e,entry.node.id)} ondragend={endLayerDrag} ondragleave={e=>{if(!(e.currentTarget as HTMLElement).contains(e.relatedTarget as Node)&&layerDrop?.id===entry.node.id)layerDrop=undefined;}}><Icon name="grip" size={12} class="layer-grip"/><Icon name={entry.node.kind==='group'?'folder':entry.node.kind==='image'?'image':'pencil'} size={14}/><span>{entry.node.label??entry.node.id}<small>{entry.node.kind}</small></span></button><span class="layer-actions"><button aria-label={`Duplicate ${entry.node.label??entry.node.id}`} title="Duplicate" disabled={saving} onclick={()=>duplicateLayer(entry.node.id)}><Icon name="copy" size={14}/></button><button aria-label={`Delete ${entry.node.label??entry.node.id}`} title="Delete" disabled={saving} onclick={()=>removeLayer(entry.node.id)}><Icon name="trash" size={14}/></button></span></li>{/each}</ol>{#if draggedLayer}<button class="scene-drop" class:drop-active={layerDrop?.placement==='root'} ondragover={e=>overLayer(e,'')} ondrop={e=>dropLayer(e,'')} ondragleave={()=>{if(layerDrop?.placement==='root')layerDrop=undefined;}}><Icon name="folder" size={14}/>Move to scene</button>{/if}<button class="add-layer" bind:this={addButton} aria-haspopup="menu" aria-controls={primitiveMenuId} aria-expanded={primitiveMenuOpen} disabled={saving} popovertarget={primitiveMenuId} onkeydown={e=>{if(e.key==='ArrowDown'){e.preventDefault();addButton?.click();}}}><Icon name="plus" size={14}/>Add</button><div class="primitive-menu" id={primitiveMenuId} bind:this={primitiveMenu} popover="auto" role="menu" tabindex="-1" aria-label="Choose primitive" style:left={`${menuPosition.left}px`} style:top={`${menuPosition.top}px`} ontoggle={()=>{primitiveMenuOpen=primitiveMenu?.matches(':popover-open')??false;if(primitiveMenuOpen)positionPrimitiveMenu();}} onkeydown={primitiveMenuKey}>{#each primitiveKinds as kind}<button role="menuitem" onclick={()=>addLayer(kind)}><Icon name={kind==='group'?'folder':kind} size={16}/>{kind[0].toUpperCase()+kind.slice(1)}</button>{/each}</div><span class="layer-announcement" role="status">{layerAnnouncement}</span><h3>Canvas</h3><div class="two"><label>Width<input type="number" value={draft.size.width} onchange={e=>mutate(next=>next.size.width=e.currentTarget.valueAsNumber)}/></label><label>Height<input type="number" value={draft.size.height} onchange={e=>mutate(next=>next.size.height=e.currentTarget.valueAsNumber)}/></label></div><label>Import artwork<input type="file" accept="image/png,image/jpeg,image/webp" onchange={e=>{void importAsset(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label></aside>
    <main class="design-canvas"><label>Appearance<select aria-label="Edit appearance" bind:value={appearanceId}><option value="">Base</option>{#each draft.design?.appearances??[] as appearance}<option value={appearance.id}>{appearance.id}</option>{/each}</select></label><p class="hint">{appearanceId?'Changes override this state. Layer structure is shared.':'Base appearance · inherited by every state.'}</p>
      {#if draft.behavior.regions.length>1}<details><summary>Combined appearance</summary><div class="two">{#each draft.behavior.regions as region}<label>{region.id}<select aria-label={`Combine ${region.id}`} value={combinedStates[region.id]??''} onchange={e=>combinedStates={...combinedStates,[region.id]:e.currentTarget.value}}><option value="">Any state</option>{#each region.states as state}<option>{state}</option>{/each}</select></label>{/each}</div><button disabled={Object.values(combinedStates).filter(Boolean).length<2} onclick={combineAppearance}><Icon name="plus" size={14}/>Edit combination</button><p class="hint">Choose at least two regions. A combined override resolves properties written by both regions.</p></details>{/if}
      <details><summary>Preview presentation</summary><div class="two">{#each draft.behavior.regions as region}<label>{region.id}<select value={previewRegions[region.id]} onchange={e=>designRegions={...designRegions,[region.id]:e.currentTarget.value}}>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label>{/each}{#each draft.visualDomains as domain}{@const signal=draft.behavior.signals.find(s=>s.id===domain.signal)}{#if signal}<label>{signal.id}{#if signal.type==='number'}<input type="number" min={signal.min} max={signal.max} value={Number(designValues[signal.id])} onchange={e=>designOverrides={...designOverrides,[signal.id]:e.currentTarget.valueAsNumber}}/>{:else}<select value={String(designValues[signal.id])} onchange={e=>designOverrides={...designOverrides,[signal.id]:scalar(signal,e.currentTarget.value)}}>{#each (signal.type==='boolean'?[false,true]:signal.values) as value}<option value={String(value)}>{String(value)}</option>{/each}</select>{/if}</label>{/if}{/each}</div></details>
      <svg bind:this={stage} viewBox={`0 0 ${draft.size.width} ${draft.size.height}`} role="group" aria-label="Source design canvas" style:aspect-ratio={`${draft.size.width}/${draft.size.height}`} onpointerdown={pressCanvas} onpointermove={e=>{hoverSelection(e);move(e);}} onpointerleave={()=>{if(!resizing)hoveredSelection=false;}} onpointerup={finishDrag} onpointercancel={cancelCanvas} onlostpointercapture={cancelCanvas}>
      {#each previewScene as node (node.id)}<GenericSceneNode {node} values={designValues} regions={previewRegions} assets={draft.assets}/>{/each}
      {#if selectedBounds && layer&&selection}<g class="selection" transform={selection.transform}><rect x={selectedBounds.x} y={selectedBounds.y} width={Math.max(1,selectedBounds.width)} height={Math.max(1,selectedBounds.height)} fill="transparent" stroke="#96ddce" stroke-width="1" stroke-dasharray="4 3" vector-effect="non-scaling-stroke"/></g><g class="resize-handles" class:visible={hoveredSelection||resizing}>{#each selection.handles as handle (handle.id)}<rect data-resize-handle={handle.id} x={handle.x-selection.handleWidth/2} y={handle.y-selection.handleHeight/2} width={selection.handleWidth} height={selection.handleHeight} fill="#96ddce" stroke="#183b3c" stroke-width="1" vector-effect="non-scaling-stroke" style:cursor={`${handle.id}-resize`} onpointerdown={e=>begin(e,handle.id)} role="presentation"/>{/each}</g>{/if}
    </svg><p class="hint">Click a component to select it. Drag to move or use its corner to resize. Expressions can bind geometry, paint and transforms to finite data.</p></main>
    <aside aria-label="Layer properties">{#if layer}<h3>{layer.kind}</h3>{#if appearanceId}<p class="hint">{draft.design?.appearances.find(a=>a.id===appearanceId)?.layers[selected]?'Overridden in this appearance':'Inherited from Base'}</p><button onclick={()=>resetAppearance()}><Icon name="undo" size={14}/>Reset override</button><button onclick={()=>resetAppearance(true)}><Icon name="arrow" size={14}/>Apply to base</button>{/if}<label>Name<input value={layer.label??''} onchange={e=>patchNode({label:e.currentTarget.value})}/></label>
      {#each ['x','y','width','height','x2','y2','radius','fontSize'] as field}{#if field in layer}<div class="property"><label>{field}<small>{propertyStatus(field)}</small>{#if !isExpression(nodeValue(field))}<input aria-label={`Layer ${field}`} type="number" value={Number(nodeValue(field))} onchange={e=>patchNode({[field]:e.currentTarget.valueAsNumber})}/>{/if}</label><button title={`Bind ${field}`} aria-label={`Bind ${field}`} onclick={()=>patchNode({[field]:isExpression(nodeValue(field))?numeric(nodeValue(field)):{ref:references[0]??''}})}><Icon name="link" size={14}/></button></div>{#if isExpression(nodeValue(field))}<GenericExpression value={expr(nodeValue(field))} {references} regions={regionIds} label={field} onchange={v=>patchNode({[field]:v})}/>{/if}{/if}{/each}
      {#each ['fill','stroke','strokeWidth','opacity','visible'] as field}<details><summary>{field}</summary><GenericExpression value={expr(nodeValue(field)??(field==='visible'?true:field==='opacity'?1:field==='strokeWidth'?0:'#72d8ca'))} {references} regions={regionIds} label={field} onchange={v=>patchNode({[field]:'literal'in v?v.literal:v})}/></details>{/each}
      {#if layer.kind==='text'}<label>Text<input aria-label="Layer text" value={typeof layer.text==='string'?layer.text:''} onchange={e=>patchNode({text:e.currentTarget.value})}/></label><details><summary>Text expression</summary><GenericExpression value={expr(layer.text)} {references} regions={regionIds} label="Text" onchange={v=>patchNode({text:'literal'in v?v.literal:v})}/></details><label>Font<select value={layer.font} onchange={e=>patchNode({font:e.currentTarget.value})}><option value="sans">Sans</option><option value="mono">Mono</option></select></label><label>Align<select value={layer.align??'left'} onchange={e=>patchNode({align:e.currentTarget.value})}><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label>{/if}
      {#if layer.kind==='path'}<label>Path data<textarea aria-label="Path data" value={typeof layer.d==='string'?layer.d:''} onchange={e=>patchNode({d:e.currentTarget.value})}></textarea></label>{/if}
      {#if layer.kind==='image'}<label>Artwork<select aria-label="Layer artwork" value={layer.assetId} onchange={e=>patchNode({assetId:e.currentTarget.value})}><option value="">Choose</option>{#each (draft.assets??[]).filter(a=>a.mime.startsWith('image/')) as asset}<option value={asset.id}>{asset.id}</option>{/each}</select></label>{/if}
      <details><summary>Transform</summary>{#each ['translateX','translateY','rotate','scaleX','scaleY','originX','originY'] as field}<GenericExpression value={expr((layer.transform as Record<string,unknown>|undefined)?.[field]??(field.startsWith('scale')?1:0))} {references} regions={regionIds} label={field} onchange={v=>patchNode({transform:{...layer?.transform,[field]:'literal'in v?v.literal:v}})}/>{/each}</details>
    {:else}<p>Select a layer.</p>{/if}
    <h3>Parameters</h3>{#each draft.parameters as parameter,i}<details><summary>{parameter.label}</summary><label>ID<input value={parameter.id} onchange={e=>mutate(next=>next.parameters[i].id=e.currentTarget.value)}/></label><label>Label<input value={parameter.label} onchange={e=>mutate(next=>next.parameters[i].label=e.currentTarget.value)}/></label><label>Type<select value={parameter.type} onchange={e=>parameterType(i,e.currentTarget.value)}>{#each ['text','color','number','boolean'] as type}<option value={type}>{type}</option>{/each}</select></label>{#if parameter.type==='boolean'}<label class="check"><input type="checkbox" checked={parameter.default} onchange={e=>mutate(next=>next.parameters[i].default=e.currentTarget.checked)}/>Default</label>{:else}<label>Default<input type={parameter.type==='number'?'number':parameter.type==='color'?'color':'text'} value={String(parameter.default)} onchange={e=>mutate(next=>next.parameters[i].default=parameter.type==='number'?e.currentTarget.valueAsNumber:e.currentTarget.value)}/></label>{/if}{#if parameter.type==='number'}<div class="two"><label>Minimum<input type="number" value={parameter.min} onchange={e=>mutate(next=>Object.assign(next.parameters[i],{min:e.currentTarget.valueAsNumber}))}/></label><label>Maximum<input type="number" value={parameter.max} onchange={e=>mutate(next=>Object.assign(next.parameters[i],{max:e.currentTarget.valueAsNumber}))}/></label></div>{/if}<button onclick={()=>mutate(next=>next.parameters.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></details>{/each}<button onclick={addParameter}><Icon name="plus" size={14}/>Add</button></aside>
  {:else if tab==='Motion'}
    <main class="form-grid"><section><h3>Baked transitions</h3><p class="hint">Tracks become finished image frames. Disabling animation preserves semantic outputs.</p>{#each draft.motions??[] as clip,ci}<article><label>ID<input value={clip.id} onchange={e=>mutate(next=>next.motions![ci].id=e.currentTarget.value)}/></label><div class="two"><label>Duration (ms)<input type="number" value={clip.durationMs} onchange={e=>mutate(next=>next.motions![ci].durationMs=e.currentTarget.valueAsNumber)}/></label><label>Frames / second<input type="number" value={clip.fps} onchange={e=>mutate(next=>next.motions![ci].fps=e.currentTarget.valueAsNumber)}/></label></div><label>Interruption<select value={clip.interruption??'snap'} onchange={e=>mutate(next=>next.motions![ci].interruption=e.currentTarget.value as 'snap')}><option value="reverse">Reverse from current progress</option><option value="restart">Restart explicit route</option><option value="snap">Snap to target</option></select></label>{#each ['from','to'] as end}<h4>{end}</h4>{#each draft.behavior.signals as signal}<label class="check"><input type="checkbox" checked={signal.id in clip[end as 'from']} onchange={e=>mutate(next=>{if(e.currentTarget.checked)next.motions![ci][end as 'from'][signal.id]=signal.initial;else delete next.motions![ci][end as 'from'][signal.id];})}/>{signal.id}</label>{#if signal.id in clip[end as 'from']}<input aria-label={`${end} ${signal.id}`} value={String(clip[end as 'from'][signal.id])} onchange={e=>mutate(next=>next.motions![ci][end as 'from'][signal.id]=scalar(signal,e.currentTarget.value))}/>{/if}{/each}{#each draft.behavior.regions as region}<label>{region.id} state<select value={clip[end==="from"?"fromRegions":"toRegions"]?.[region.id]??""} onchange={e=>mutate(next=>{const key=end==="from"?"fromRegions":"toRegions";const states=next.motions![ci][key]??={};if(e.currentTarget.value)states[region.id]=e.currentTarget.value;else delete states[region.id];})}><option value="">Keep region</option>{#each region.states as state}<option value={state}>{state}</option>{/each}</select></label>{/each}{/each}
    {#each clip.tracks as track,ti}<details open><summary>{track.node} · {track.property}</summary><label>Layer<select value={track.node} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].node=e.currentTarget.value)}>{#each layerList as entry}<option value={entry.node.id}>{entry.node.label??entry.node.id}</option>{/each}</select></label><label>Property<select value={track.property} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].property=e.currentTarget.value)}>{#each ['x','y','width','height','radius','opacity','strokeWidth','transform.translateX','transform.translateY','transform.rotate','transform.scaleX','transform.scaleY'] as property}<option value={property}>{property}</option>{/each}</select></label><label>Easing<select value={track.easing??'linear'} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].easing=e.currentTarget.value as 'linear')}>{#each ['linear','ease-in','ease-out','ease-in-out'] as easing}<option value={easing}>{easing}</option>{/each}</select></label>{#each track.keyframes as keyframe,ki}<div class="three"><label>Time (0–1)<input type="number" min="0" max="1" step=".01" value={keyframe.at} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].keyframes[ki].at=e.currentTarget.valueAsNumber)}/></label><label>Value<input type="number" value={keyframe.value} onchange={e=>mutate(next=>next.motions![ci].tracks[ti].keyframes[ki].value=e.currentTarget.valueAsNumber)}/></label><button title="Delete keyframe" aria-label="Delete keyframe" onclick={()=>mutate(next=>next.motions![ci].tracks[ti].keyframes.splice(ki,1))}><Icon name="trash" size={14}/></button></div>{/each}<button onclick={()=>mutate(next=>next.motions![ci].tracks[ti].keyframes.push({at:.5,value:0}))}><Icon name="plus" size={14}/>Add keyframe</button><button onclick={()=>mutate(next=>next.motions![ci].tracks.splice(ti,1))}><Icon name="trash" size={14}/>Delete track</button></details>{/each}<button onclick={()=>mutate(next=>next.motions![ci].tracks.push({node:layerList[0]?.node.id??'',property:'opacity',keyframes:[{at:0,value:0},{at:1,value:1}]}))}><Icon name="plus" size={14}/>Add track</button><button onclick={()=>mutate(next=>next.motions!.splice(ci,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.motions??=[]).push({id:id('motion'),from:Object.fromEntries(next.visualDomains.map(d=>[d.signal,d.values?.[0]??d.min??0])),to:Object.fromEntries(next.visualDomains.map(d=>[d.signal,d.values?.at(-1)??d.max??1])),durationMs:200,fps:30,tracks:[],interruption:'snap'}))}><Icon name="plus" size={14}/>Add</button></section><section><h3>Playback rules</h3><p>Transition tracks modify authoring layers during compilation. The player receives their baked frame sequence, duration and interruption rule.</p><p>For rapidly changing gauges, use finite sampled images and direct value selection. Live values continue when animation is disabled.</p><p>Use Try to test rapid reversal, cancellation and reduced motion.</p></section></main>
  {:else if tab==='Sound'}
    <main class="form-grid"><section><h3>Optional sound cues</h3><p class="hint">Import PCM16 WAV, up to ten seconds. Silent visuals must communicate the same condition.</p><label>Import sound<input type="file" accept="audio/wav,.wav" onchange={e=>{void importAsset(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label>{#each draft.sounds??[] as sound,i}<article><label>ID<input value={sound.id} onchange={e=>mutate(next=>next.sounds![i].id=e.currentTarget.value)}/></label><label>Behavior cue<input value={sound.cue} onchange={e=>mutate(next=>next.sounds![i].cue=e.currentTarget.value)}/></label><label>Audio asset<select value={sound.assetId} onchange={e=>mutate(next=>next.sounds![i].assetId=e.currentTarget.value)}><option value="">Choose</option>{#each (draft.assets??[]).filter(a=>a.mime==='audio/wav') as asset}<option value={asset.id}>{asset.id}</option>{/each}</select></label><div class="two"><label>Cooldown (ms)<input type="number" min="0" value={sound.cooldownMs??0} onchange={e=>mutate(next=>next.sounds![i].cooldownMs=e.currentTarget.valueAsNumber)}/></label><label>Volume (0–1)<input type="number" min="0" max="1" step=".1" value={sound.volume??1} onchange={e=>mutate(next=>next.sounds![i].volume=e.currentTarget.valueAsNumber)}/></label></div><label class="check"><input type="checkbox" checked={sound.stopOnExit??true} onchange={e=>mutate(next=>next.sounds![i].stopOnExit=e.currentTarget.checked)}/>Stop on state exit</label><button onclick={()=>mutate(next=>next.sounds!.splice(i,1))}><Icon name="trash" size={14}/>Delete</button></article>{/each}<button onclick={()=>mutate(next=>(next.sounds??=[]).push({id:id('sound'),cue:'click',assetId:next.assets?.find(a=>a.mime==='audio/wav')?.id??'',cooldownMs:100,volume:1,stopOnExit:true}))}><Icon name="plus" size={14}/>Add</button></section><section><h3>Availability</h3><p>Audio capability controls compilation. Browser playback additionally requires a user gesture and respects mute and hidden-window state.</p><p>Cues received while unavailable are discarded. Unlocking, reconnecting or restoring a snapshot never replays old sound.</p><p>Add a cue effect to a transition in States to trigger a sound.</p></section></main>
  {:else}
    <main class="try-layout">{#if busy}<section class="preview-loading" aria-label="Preparing preview" aria-busy="true"><div><h3>Preparing preview…</h3><progress aria-label="Widget compilation" max="1" value={compilationProgress}></progress><p role="status">{compilationProgress===undefined?'Preparing assets…':`${Math.floor(compilationProgress*100)}%`}</p><button onclick={invalidate}><Icon name="stop" size={16}/>Cancel</button></div></section>{:else if compiled}<section class="try-canvas"><div style:aspect-ratio={`${compiled.artifact.width}/${compiled.artifact.height}`} style:width={`${compiled.artifact.width}px`}><CompiledWidget bind:this={tryPlayer} bundle={compiled} name={draft.title} {muted} showAudioControls onoutput={output=>outputs={...outputs,[output.port]:output.value}} onstate={state=>tryState=state} ontrace={rows=>trace=[...trace,...rows].slice(-100)}/></div><div class="actions"><button onclick={()=>tryPlayer?.reset()}><Icon name="refresh" size={14}/>Reset</button><label class="check"><input type="checkbox" bind:checked={muted}/>Mute</label></div><h3>Result</h3>{#if tryState}<dl>{#each Object.entries(tryState.values) as [key,value]}<div><dt>{key}</dt><dd>{String(value)}</dd></div>{/each}{#each Object.entries(tryState.regions) as [key,value]}<div><dt>State · {key}</dt><dd>{value}</dd></div>{/each}</dl>{/if}<h3>Transition trace</h3><ol class="trace">{#each trace as row}<li>{row.atMs} · {row.event} · {row.region}: {row.from} → {row.to}</li>{/each}</ol><h3>Emitted outputs</h3><dl>{#each Object.entries(outputs) as [key,value]}<div><dt>{key}</dt><dd>{String(value)}</dd></div>{/each}</dl></section><aside><h3>Simulate</h3><p class="hint">Requested state changes through the widget or events. Confirmation and quality are separate samples.</p>{#each draft.behavior.signals.filter(s=>s.source!=='local') as signal}<article><h4>{signal.id} · {signal.source}</h4>{#if signal.source==='feedback'}<label>Quality<select value={qualities[signal.id]??'unknown'} onchange={e=>qualities={...qualities,[signal.id]:e.currentTarget.value}}>{#each ['fresh','unknown','stale','disconnected'] as quality}<option value={quality}>{quality}</option>{/each}</select></label>{/if}<label>Value{#if signal.type==='boolean'||signal.type==='enum'}<select value={String((signal.source==='feedback'?feedbackValues:inputValues)[signal.id]??signal.initial)} onchange={e=>{if(signal.source==='feedback')feedbackValues={...feedbackValues,[signal.id]:scalar(signal,e.currentTarget.value)};else inputValues={...inputValues,[signal.id]:scalar(signal,e.currentTarget.value)};}}>{#each (signal.type==='boolean'?[false,true]:signal.values) as value}<option value={String(value)}>{String(value)}</option>{/each}</select>{:else}<input type="number" min={signal.min} max={signal.max} value={Number((signal.source==='feedback'?feedbackValues:inputValues)[signal.id]??signal.initial)} onchange={e=>{if(signal.source==='feedback')feedbackValues={...feedbackValues,[signal.id]:e.currentTarget.valueAsNumber};else inputValues={...inputValues,[signal.id]:e.currentTarget.valueAsNumber};}}/>{/if}</label></article>{/each}<label>Event<select bind:value={selectedEvent}>{#each draft.behavior.events as event}<option value={event.id}>{event.id}</option>{/each}</select></label><button onclick={()=>simulation(selectedEvent)}><Icon name="play" size={14}/>Send</button><CompiledArtifactInspector bundle={compiled} capabilities={BROWSER_WIDGET_CAPABILITIES}/></aside>{:else}<section class="empty"><Icon name="monitor" size={36}/><h3>{error?'Preview unavailable':'Preview not compiled'}</h3><p>{error?'Fix the design or target settings, then retry.':'Open Preview or compile to prepare the current design.'}</p><button onclick={()=>void compile()}><Icon name="refresh" size={16}/>Retry</button></section>{/if}</main>
  {/if}
  </div>
</section>

<style>
  .preview-loading{grid-column:1/-1;display:grid;place-items:center;min-height:500px;text-align:center}.preview-loading>div{width:min(320px,100%)}.preview-loading h3{margin:0 0 18px}.preview-loading progress{display:block;width:100%;height:10px;accent-color:#86cbb9;border:0;border-radius:6px;overflow:hidden}.preview-loading progress::-webkit-progress-bar{background:var(--surface,#17252d);border-radius:6px}.preview-loading progress::-webkit-progress-value{background:#86cbb9;border-radius:6px}.preview-loading p{font-size:12px;color:var(--muted,#91a5b0)}
  .trace{max-height:180px;overflow:auto;font:11px monospace}

  .layers .group-toggle{position:absolute;top:50%;transform:translateY(-50%);width:18px;height:24px;min-width:0;padding:0;background:transparent;border:0;z-index:1}
  .group-toggle.expanded :global(svg){transform:rotate(90deg)}
  .generic-designer{width:100%;min-width:0;box-sizing:border-box;color:var(--text);font:inherit}.title{display:block;font:inherit;letter-spacing:inherit;border:0;background:transparent;padding:0;width:100%;min-width:0}.actions{display:flex;gap:6px;align-items:center}.save-action{display:inline-flex}.save-action button:disabled{pointer-events:none}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;font:inherit;font-size:var(--ui-action-size);color:inherit;background:var(--surface,#17252d);border:1px solid var(--line,#30434e);border-radius:5px;padding:7px 10px;cursor:pointer}button:hover{border-color:#83c8b7}button:disabled{opacity:.4;cursor:default}.primary{background:#295447;border-color:#659f88}button.active{background:#285347;border-color:#86cbb9}nav{display:flex;flex-direction:row;align-items:center;justify-content:flex-start;width:auto;min-height:0;gap:5px;padding:10px 0;background:transparent;border-bottom:1px solid var(--line)}nav button{width:auto;flex:0 0 auto;border:1px solid transparent;background:transparent}.buildbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:7px 0;border-bottom:1px solid var(--line);min-height:48px}.buildbar label{margin:0;font-size:var(--ui-text-size)}.buildbar input[type=number]{width:70px}.buildbar>span{font-size:var(--ui-text-size);color:#9cb5bd}.workspace{overflow:auto;min-height:580px}.workspace.design{height:70vh;display:grid;grid-template-columns:210px minmax(260px,1fr) 300px;overflow:hidden}aside{padding:var(--ui-panel-padding);overflow:auto;min-width:0;border-right:1px solid var(--line,#30434e)}.design>aside:last-child{border-left:1px solid var(--line,#30434e);border-right:0}.design-canvas{background:#0c1720;padding:15px;overflow:auto;min-width:0}.design-canvas>svg{user-select:none;touch-action:none;display:block;width:100%;max-height:580px;min-height:200px;background-image:linear-gradient(#344c551a 1px,transparent 1px),linear-gradient(90deg,#344c551a 1px,transparent 1px);background-size:20px 20px;overflow:visible}.selection{cursor:move;touch-action:none}.resize-handles{opacity:0;pointer-events:none}.resize-handles.visible{opacity:1;pointer-events:auto}label{display:grid;gap:5px;font-size:var(--ui-text-size);color:#bed0d5;margin:9px 0}input,select,textarea{min-width:0;width:100%;box-sizing:border-box;padding:7px;border:1px solid #3a5360;border-radius:4px;background:var(--bg,#0d1820);color:var(--text,#deecee);font:inherit;font-size:var(--ui-text-size)}input[type=checkbox]{width:auto}input[type=color]{height:33px;padding:2px}textarea{min-height:75px;resize:vertical}.check{display:flex;align-items:center;gap:7px}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.three{display:grid;grid-template-columns:1fr 1fr 30px;gap:7px;align-items:center}.property{display:flex;align-items:center;gap:5px}.property>label{flex:1}.property>button{margin-top:14px;padding:6px}.layer-hint{font-size:var(--ui-text-size);color:#8ea8b1;line-height:var(--ui-line-height)}.layer-announcement{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.add-layer{width:100%;justify-content:flex-start;margin:4px 0 8px;background:transparent;border-color:transparent}.primitive-menu{position:fixed;inset:auto;margin:0;padding:5px;width:180px;max-height:calc(100vh - 16px);overflow:auto;background:var(--surface,#17252d);color:#deecee;border:1px solid var(--line,#30434e);border-radius:7px;box-shadow:0 8px 24px #0006}.primitive-menu:popover-open{display:grid;gap:2px}.primitive-menu button{justify-content:flex-start;border-color:transparent;background:transparent}.primitive-menu button:hover,.primitive-menu button:focus-visible{background:#285347}.layers{padding:0;margin:0;list-style:none}.layers li{position:relative}.layers li.dragging{opacity:.45}.layers li.drop-inside>.layer-select{outline:1px solid #96ddce;outline-offset:-1px;background:#285347}.scene-drop{width:100%;margin:5px 0;border-style:dashed;background:transparent}.scene-drop.drop-active{border-color:#96ddce;background:#285347}.layers li.drop-before::before,.layers li.drop-after::after{content:"";position:absolute;left:0;right:0;height:2px;background:#96ddce;pointer-events:none}.layers li.drop-before::before{top:0}.layers li.drop-after::after{bottom:0}.layers .layer-select{cursor:grab}.layers .layer-select:active{cursor:grabbing}.layers :global(.layer-grip){flex-shrink:0;color:#8ea8b1}.layers .layer-select{width:100%;justify-content:start;text-align:left;border-color:transparent;margin:2px 0;font-size:11px}.layers .layer-select>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.layer-actions{position:absolute;right:3px;top:50%;transform:translateY(-50%);display:flex;gap:2px;padding:2px;background:var(--surface,#17252d);border-radius:4px;opacity:0;pointer-events:none}.layers li:hover .layer-actions,.layers li:focus-within .layer-actions{opacity:1;pointer-events:auto}.layers li:hover .layer-select,.layers li:focus-within .layer-select{padding-right:60px}.layer-actions button{width:24px;height:26px;margin:0;padding:4px;justify-content:center;cursor:pointer;background:transparent}.layer-actions button:hover:enabled{background:#285347}.layers small{display:block;font-size:9px;color:#8ea8b1}h3{font-size:var(--ui-heading-size);margin:16px 0 9px}h3:first-child{margin-top:0}h3 small{font-size:var(--ui-text-size);font-weight:400;color:#8aa4af}h4{font-size:var(--ui-heading-size);margin:10px 0 6px}p{font-size:var(--ui-text-size);line-height:var(--ui-line-height)}.hint{font-size:var(--ui-text-size);color:#8ea9b5;margin:8px 0 14px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--ui-section-gap);max-width:1250px;margin:auto;padding:var(--ui-panel-padding)}.form-grid>section{min-width:0}article{padding:12px 14px;border:1px solid #304b58;border-radius:7px;margin:12px 0;background:var(--surface,#17252d)}article>button,details>button{margin-right:6px;margin-top:7px;font-size:11px}details{border-top:1px solid #2c4551;margin:10px 0;padding:9px 0}summary{cursor:pointer;color:#b2d4d6;font-size:12px}.try-layout{display:grid;grid-template-columns:minmax(260px,1fr) 340px;gap:var(--ui-section-gap);padding:var(--ui-panel-padding)}.try-canvas{min-width:0}.try-canvas>div:first-child{max-height:540px;max-width:100%;margin:15px auto;background:transparent}.try-canvas>.actions{margin:12px 0}.try-layout aside{border:0;padding:0 8px}.empty{grid-column:1/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:300px;text-align:center;color:#a2bec9}.empty p{max-width:430px}dl{font-size:var(--ui-text-size);margin:10px 0}dl>div{display:flex;justify-content:space-between;gap:16px;padding:5px;border-bottom:1px solid #263d49}dt{color:#94b1bc;overflow-wrap:anywhere}dd{margin:0;overflow-wrap:anywhere;text-align:right}.error{padding:9px 20px;margin:0;background:#512b31;color:#ffccbd;font-size:12px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #9adbc8;outline-offset:2px}@media(max-width:1000px){.workspace.design{grid-template-columns:170px minmax(220px,1fr) 250px}.buildbar{gap:6px}.try-layout{grid-template-columns:1fr 280px}}@media(max-width:750px){.generic-designer{overflow:auto}.workspace{height:auto;overflow:visible}.workspace.design{grid-template-columns:150px 1fr;overflow:visible}.design>aside:last-child{grid-column:1/-1}.form-grid,.try-layout{grid-template-columns:1fr;padding:14px}.buildbar{padding:8px}nav{overflow:auto;padding:7px}}
</style>
